INSERT OR REPLACE INTO messages (id, channel_id, sender_id, content, attachments, nonce, created_at, reply_to_id, reply_to_content, reply_to_author) VALUES ('announcement_1_1c6f94bc', 'announcements', '4fecc8e6-2d27-4560-886b-ec88edeaa48a', '🚀 **vConnect Platform Release v1.2.0 is Live!**

